const URLS = [
  'https://j1visa.state.gov/programs/summer-work-travel/',
  'https://j1visa.state.gov/summer-work-travel-resource-page/',
  'https://travel.state.gov/content/travel/en/us-visas/study/exchange.html',
  'https://j1visa.state.gov/participants/how-to-apply/sponsor-search/',
  'https://www.armadagrandee.com/work-and-travel/basvuru-sartlari',
  'https://compassabroad.com.tr/work-and-travel',
  'https://frontedu.com.tr/work-and-travel-2027/',
  'https://edufix.com.tr/work-and-travel-basvuru-tarihleri/',
  'https://www.success.com.tr/work-and-travel',
  'https://edex.com.tr/',
  'https://www.oxfordhousewat.com/',
  'https://campusedu.com.tr/work-and-travel/',
  'https://www.elt.com.tr/workandtravel',
  'https://westline.com.tr/work-and-travel/',
  'https://edumaster.com.tr/',
];
const rows = $input.all().map(i => i.json).filter(r => r && r.page_url);
const map = {};
for (const r of rows) {
  map[String(r.page_url)] = {
    hash: r.content_hash ? String(r.content_hash) : '',
    text: r.content_text ? String(r.content_text) : '',
  };
}
return URLS.map(u => ({ json: {
  url: u,
  previous_hash: (map[u] && map[u].hash) || '',
  previous_text: (map[u] && map[u].text) || '',
} }));

const url = $('Prepare URLs').item.json.url;
const prev = $('Prepare URLs').item.json.previous_hash || '';
const prevText = $('Prepare URLs').item.json.previous_text || '';
let html = String($json.data || '');

// Remove non-content markup blocks
html = html.replace(/<script[\s\S]*?<\/script>/gi, ' ');
html = html.replace(/<style[\s\S]*?<\/style>/gi, ' ');
html = html.replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');
html = html.replace(/<!--[\s\S]*?-->/g, ' ');

// Turn block-level boundaries into line breaks
html = html.replace(/<br\s*\/?>/gi, '\n');
html = html.replace(/<\/(p|div|li|h[1-6]|section|article|header|footer|nav|tr|ul|ol|table|thead|tbody)>/gi, '\n');

// Strip remaining tags
let raw = html.replace(/<[^>]+>/g, ' ');

// Decode common HTML entities
raw = raw
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'");

// Normalize visible-text lines
let lines = raw.split(/\n+/)
  .map(l => l.replace(/\s+/g, ' ').trim())
  .filter(l => l.length > 0);

// Remove known dynamic/non-content noise
lines = lines.filter(line => {
  if (/Cloudflare Ray ID\s*:/i.test(line)) return false;
  if (/Ray ID\s*:/i.test(line)) return false;
  return true;
});

const newText = lines.join('\n');

// djb2 hash
function makeHash(text) {
  let h = 5381;
  for (let i = 0; i < text.length; i++) {
    h = ((h << 5) + h + text.charCodeAt(i)) >>> 0;
  }
  return String(h) + ':' + String(text.length);
}

const contentHash = makeHash(newText);

const fetchFailed = newText.length === 0;
const isFirst = prev === '';

const effectiveHash = (fetchFailed && prev) ? prev : contentHash;
const effectiveText = (fetchFailed && prevText) ? prevText : newText;

// Normalize previous saved text too.
// This prevents old Cloudflare Ray IDs from causing a false change
// after this filter is introduced.
const previousLines = prevText
  ? prevText.split('\n')
      .map(l => l.replace(/\s+/g, ' ').trim())
      .filter(l => l.length > 0)
      .filter(line => !/Cloudflare Ray ID\s*:/i.test(line))
      .filter(line => !/Ray ID\s*:/i.test(line))
  : [];

const normalizedPrevText = previousLines.join('\n');

// If previous text exists, compare normalized previous content.
// This makes the new filter compatible with old saved data.
const comparisonPrevHash = prevText
  ? makeHash(normalizedPrevText)
  : prev;

const changed = !fetchFailed && !isFirst && comparisonPrevHash !== contentHash;

// Compute changed visible text
const prevLines = normalizedPrevText ? normalizedPrevText.split('\n') : [];
const prevSet = new Set(prevLines);
const newSet = new Set(lines);

const added = lines.filter(l => !prevSet.has(l));
const removed = prevLines.filter(l => !newSet.has(l));

let diffParts = [];

if (added.length) {
  diffParts.push('ADDED / CHANGED:\n' + added.join('\n'));
}

if (removed.length) {
  diffParts.push('REMOVED:\n' + removed.join('\n'));
}

let changedText = diffParts.join('\n\n');

if (changedText.length > 8000) {
  changedText = changedText.slice(0, 8000);
}

return {
  json: {
    page_url: url,
    content_hash: effectiveHash,
    content_text: effectiveText,
    previous_hash: prev,
    changed: changed,
    is_first: isFirst,
    fetch_failed: fetchFailed,
    changed_text: changedText,
    checked_at: new Date().toISOString(),
  }
};

